package Docs;
use strict;
use warnings;

# Return the contents of a help page stored under $root.
sub read_page {
    my ($root, $name) = @_;
    open(my $fh, '<', "$root/$name") or die "cannot open $name: $!";
    local $/;
    my $content = <$fh>;
    close $fh;
    return $content;
}

1;

use strict;
use warnings;
use File::Temp qw(tempdir);
use Test::More;
use Docs;

subtest reads_page => sub {
    my $dir = tempdir(CLEANUP => 1);
    open(my $fh, '>', "$dir/intro.txt") or die $!;
    print {$fh} 'welcome';
    close $fh;
    is(Docs::read_page($dir, 'intro.txt'), 'welcome', 'page content');
};

done_testing;
